const reviewedExam = exam.map((item) => ({
  ...item,
  options: [
    item.options[item.answer],
    ...(examDistractors[item.id] ?? item.options.slice(1)),
  ],
}));

const balance = (pool) =>
  pool.map((item, index) => {
    const target = index % 4;
    const options = item.options.slice();
    const correct = options.splice(item.answer, 1)[0];
    options.splice(target, 0, correct);
    return { ...item, options, answer: target };
  });

export const advancedLanguagePools = {
  middle: balance(middle),
  high1: balance(high1),
  exam: balance(reviewedExam),
};
